    "7/8 MHz nur über den Modulator/Loop auf dem Pluto (9,14 bzw. 8,0 MS/s); 6 MHz läuft per USB (6,857 MS/s), ist in EU-Receivern aber oft nur manuell abstimmbar": "7/8 MHz uniquement via le modulateur/la boucle sur le Pluto (9,14 ou 8,0 MS/s) ; 6 MHz passe par USB (6,857 MS/s), mais ne s’accorde souvent que manuellement sur les récepteurs européens",
