    "Alle Modulationsparameter brauchen „Übernehmen (Neustart)“. Die Nutzbitrate bestimmt das TS-Budget im Bereich „Programme“.": "Tous les paramètres de modulation nécessitent « Appliquer (redémarrage) ». Le débit utile détermine le budget TS dans la section « Programmes ».",
