    "6,900 MBd = deutsches Kabel (Auto-Suchlauf), 6,875 Pflicht in Suchlauflisten, 3,450 MBd läuft per USB (manuelle Eingabe am Receiver)": "6,900 MBd = câble allemand (recherche auto), 6,875 obligatoire dans les listes de recherche, 3,450 MBd passe par USB (saisie manuelle sur le récepteur)",
