    "Nutzbitrate = SR · log2(M) · 188/204. Für 6,9 MBd sind 13,8 MS/s nötig – nur zyklischer Puffer/Modulator auf dem Pluto.": "Débit utile = SR · log2(M) · 188/204. 6,9 MBd nécessite 13,8 MS/s – uniquement tampon cyclique/modulateur sur le Pluto.",
    "Sat-Eingang führt 13/18 V – DC-Block bzw. LNB-Speisung am Receiver aus!": "L’entrée satellite porte 13/18 V – bloc DC ou alimentation LNB désactivée sur le récepteur !",
    "Der Receiver speist über den Sat-Eingang das LNB (13 V = V, 18 V = H, 22 kHz = High-Band). Ohne DC-Block (Gleichspannungstrenner) zwischen Pluto-TX und Receiver wird der Pluto beschädigt. Zusätzlich LNB-Speisung im Receiver-Menü abschalten, wenn möglich.": "Le récepteur alimente le LNB via l’entrée satellite (13 V = V, 18 V = H, 22 kHz = bande haute). Sans bloc DC entre le Pluto TX et le récepteur, le Pluto sera endommagé. Désactivez aussi l’alimentation LNB dans le menu du récepteur si possible.",
