    "Der Pluto liefert höchstens +7 dBm; für QO-100 folgen Filter, Endstufe und Spiegel. Bandplan, Leistungsgrenzen und die Regeln des Transponders (BATC/AMSAT-DL) beachten. Stationskennung: das Rufzeichen steht im Programm-/Anbieternamen.": "Le Pluto fournit au maximum +7 dBm ; pour QO-100 suivent filtre, amplificateur et parabole. Respectez le plan de bande, les limites de puissance et les règles du transpondeur (BATC/AMSAT-DL). Identification : l’indicatif figure dans le nom du programme/fournisseur.",
