    "Nutzbitrate steigt mit Konstellation/Coderate (DVB-T) bzw. Symbolrate/QAM (DVB-C); sonst Video-/Audiobitraten senken oder ein Programm entfernen. SI-Tabellen brauchen ≈ 60 kbit/s, Rest wird mit Nullpaketen aufgefüllt (CBR).": "Le débit utile augmente avec la constellation/le taux de codage (DVB-T) ou le débit de symboles/la QAM (DVB-C) ; sinon, réduisez les débits vidéo/audio ou supprimez un programme. Les tables SI nécessitent ≈ 60 kbit/s, le reste est complété par des paquets nuls (CBR).",
