    "Sat-Eingang führt 13/18 V – DC-Block bzw. LNB-Speisung am Receiver aus!": "La entrada de satélite lleva 13/18 V: ¡bloqueo de CC o alimentación LNB desactivada en el receptor!",
    "Der Receiver speist über den Sat-Eingang das LNB (13 V = V, 18 V = H, 22 kHz = High-Band). Ohne DC-Block (Gleichspannungstrenner) zwischen Pluto-TX und Receiver wird der Pluto beschädigt. Zusätzlich LNB-Speisung im Receiver-Menü abschalten, wenn möglich.": "El receptor alimenta el LNB por la entrada de satélite (13 V = V, 18 V = H, 22 kHz = banda alta). Sin bloqueo de CC entre el Pluto TX y el receptor, el Pluto se dañará. Desactive también la alimentación LNB en el menú del receptor si es posible.",
