    "Feldtest TV": "Prueba de campo TV",
    "Am Fernseher bestätigte Werte: DVB-T K36 594 MHz 8k/16-QAM/2/3/GI 1/4 HD, DVB-C 546 MHz 64-QAM 6900 kBd SD, PAL K36 B/G, DVB-S 11 038 MHz V 22 000 kS/s QPSK 7/8 (3 Dienste) bzw. 1/2.": "Valores confirmados en el televisor: DVB-T K36 594 MHz 8k/16-QAM/2/3/GI 1/4 HD, DVB-C 546 MHz 64-QAM 6900 kBd SD, PAL K36 B/G, DVB-S 11 038 MHz V 22 000 kS/s QPSK 7/8 (3 servicios) o 1/2.",
    "DVB-T K36 594 MHz · 8k 16-QAM 2/3 GI 1/4 · HD": "DVB-T K36 594 MHz · 8k 16-QAM 2/3 GI 1/4 · HD",
    "TV: Antenne → DVB-T → Suchlauf (oder manuell K36, 8 MHz). Dienst „DABLAB Test“ in HD (H.264 1080p25 + AAC), EIT prüfen. Modulator auf dem Pluto (8 MHz).": "TV: Antena → DVB-T → búsqueda (o manual K36, 8 MHz). Comprobar el servicio «DABLAB Test» en HD (H.264 1080p25 + AAC) y la EIT. Modulador en el Pluto (8 MHz).",
    "Dienst „DABLAB Test“ in HD gefunden, Bild und Ton, EIT sichtbar.": "Servicio «DABLAB Test» encontrado en HD, imagen y audio, EIT visible.",
    "DVB-C 546 MHz · 64-QAM 6900 kBd · SD": "DVB-C 546 MHz · 64-QAM 6900 kBd · SD",
    "TV: Kabel → Suchlauf (vollständig oder manuell 546 MHz, 6900 kS/s, 64-QAM). Dienst „DABLAB Kabel“ prüfen.": "TV: Cable → búsqueda (completa o manual 546 MHz, 6900 kS/s, 64-QAM). Comprobar el servicio «DABLAB Kabel».",
    "Dienst „DABLAB Kabel“ in SD (MPEG-2 + MP2) gefunden.": "Servicio «DABLAB Kabel» encontrado en SD (MPEG-2 + MP2).",
    "PAL K36 (Bild 591,25 MHz) B/G": "PAL K36 (vídeo 591,25 MHz) B/G",
    "TV: Analog → Suchlauf oder manuell 591,25 MHz, System B/G. Testbild, Text und Ton prüfen.": "TV: Analógico → búsqueda o manual 591,25 MHz, sistema B/G. Comprobar carta de ajuste, texto y audio.",
    "Farbbalken mit Text „Feldtest TV“, Ton 1 kHz.": "Barras de color con el texto «Feldtest TV», tono de 1 kHz.",
    "DVB-S 11 038 MHz V · 22 000 kS/s · QPSK 7/8 · 3 Dienste (HD/UHD/HDR10)": "DVB-S 11 038 MHz V · 22 000 kS/s · QPSK 7/8 · 3 servicios (HD/UHD/HDR10)",
    "⚠️ DC-Block zwischen Pluto und Sat-Eingang! LNB-Speisung am Receiver aus. TV: Satellit → manueller Transponder 11 038 MHz V, 22 000 kS/s, LOF 9750 (Low-Band, 22 kHz aus) → Sat-ZF 1288 MHz. Modulator auf dem Pluto.": "⚠️ ¡Bloqueo de CC entre el Pluto y la entrada de satélite! Alimentación LNB del receptor desactivada. TV: Satélite → transpondedor manual 11 038 MHz V, 22 000 kS/s, LOF 9750 (banda baja, 22 kHz desactivado) → FI sat 1288 MHz. Modulador en el Pluto.",
    "Drei Dienste: HD (H.264), UHD (HEVC), HDR10 (HEVC Main10) – HDR-Kennung am TV.": "Tres servicios: HD (H.264), UHD (HEVC), HDR10 (HEVC Main10); indicación HDR en el televisor.",
    "DVB-S 11 038 MHz V · 22 000 kS/s · QPSK 1/2 · 1 Dienst": "DVB-S 11 038 MHz V · 22 000 kS/s · QPSK 1/2 · 1 servicio",
    "Wie oben, FEC 1/2 (robuster). Receiver neu abstimmen.": "Como arriba, FEC 1/2 (más robusto). Volver a sintonizar el receptor.",
    "Dienst „DABLAB Sat“ (HD H.264) gefunden.": "Servicio «DABLAB Sat» (HD H.264) encontrado.",
    "DVB-S/S2: Symbolraten & FEC": "DVB-S/S2: tasas de símbolos y FEC",
    "DVB-S QPSK 1/2…7/8 bei 6000 kS/s, DVB-S2 QPSK/8PSK mit Rolloff 0,20/0,35 – ⚠️ nur mit DC-Block.": "DVB-S QPSK 1/2…7/8 a 6000 kS/s, DVB-S2 QPSK/8PSK con roll-off 0,20/0,35; ⚠️ solo con bloqueo de CC.",
    "Receiver neu abstimmen (manueller Transponder), Lock und Bild prüfen.": "Volver a sintonizar el receptor (transpondedor manual), comprobar enganche e imagen.",
    "Lock, Bild/Ton fehlerfrei.": "Enganche, imagen/audio sin errores.",
