    "Alle Modulationsparameter brauchen „Übernehmen (Neustart)“. Die Nutzbitrate bestimmt das TS-Budget im Bereich „Programme“.": "Tutti i parametri di modulazione richiedono «Applica (riavvio)». Il bitrate utile determina il budget TS nella sezione «Programmi».",
