    "Sat-Eingang führt 13/18 V – DC-Block bzw. LNB-Speisung am Receiver aus!": "L’ingresso satellite porta 13/18 V – DC block o alimentazione LNB disattivata sul ricevitore!",
    "Der Receiver speist über den Sat-Eingang das LNB (13 V = V, 18 V = H, 22 kHz = High-Band). Ohne DC-Block (Gleichspannungstrenner) zwischen Pluto-TX und Receiver wird der Pluto beschädigt. Zusätzlich LNB-Speisung im Receiver-Menü abschalten, wenn möglich.": "Il ricevitore alimenta l’LNB tramite l’ingresso satellite (13 V = V, 18 V = H, 22 kHz = banda alta). Senza DC block tra Pluto TX e ricevitore il Pluto si danneggia. Se possibile, disattivare anche l’alimentazione LNB nel menu del ricevitore.",
