    "DATV sendet direkt auf der Amateurfunkfrequenz, IQ per USB – nur mit Amateurfunkzulassung": "La DATV trasmette direttamente sulla frequenza radioamatoriale, IQ via USB – solo con licenza di radioamatore",
    "Amateurfunk: Senden nur mit gültiger Zulassung und eigenem Rufzeichen.": "Radioamatori: trasmettere solo con licenza valida e nominativo proprio.",
    "Der Pluto liefert höchstens +7 dBm; für QO-100 folgen Filter, Endstufe und Spiegel. Bandplan, Leistungsgrenzen und die Regeln des Transponders (BATC/AMSAT-DL) beachten. Stationskennung: das Rufzeichen steht im Programm-/Anbieternamen.": "Il Pluto fornisce al massimo +7 dBm; per QO-100 seguono filtro, amplificatore e parabola. Rispettare il band plan, i limiti di potenza e le regole del transponder (BATC/AMSAT-DL). Identificazione: il nominativo è nel nome del programma/fornitore.",
