    "Codec-Matrix": "Matrice codec",
    "AAC-LC, HE-AAC und HE-AAC v2 × 32/48 kHz × Mono/Stereo – alle Kombinationen gleichzeitig im Ensemble.": "AAC-LC, HE-AAC e HE-AAC v2 × 32/48 kHz × mono/stereo – tutte le combinazioni contemporaneamente nell’ensemble.",
    "Alle Codec-Kombinationen": "Tutte le combinazioni di codec",
    "Jeden Dienst am Prüfling anwählen. Ton (unterschiedliche Frequenz je Dienst), Codec-Anzeige und Kanalzahl kontrollieren.": "Selezionare ogni servizio sul dispositivo in prova. Controllare audio (frequenza diversa per servizio), indicazione del codec e numero di canali.",
    "Alle 10 Dienste dekodieren ohne Aussetzer; Mono-Dienste mittig, Stereo-Dienste auf beiden Kanälen.": "Tutti i 10 servizi si decodificano senza interruzioni; servizi mono al centro, stereo su entrambi i canali.",
    "Bitraten & Fehlerschutz": "Bitrate e protezione dagli errori",
    "Bitraten 8–192 kbit/s sowie alle EEP-A/B-Schutzstufen bei 64 kbit/s.": "Bitrate 8–192 kbit/s e tutti i livelli di protezione EEP-A/B a 64 kbit/s.",
    "Bitraten-Matrix (EEP 3-A)": "Matrice bitrate (EEP 3-A)",
    "Alle Dienste nacheinander anwählen, Bitratenanzeige und Klang prüfen.": "Selezionare tutti i servizi uno dopo l’altro; verificare l’indicazione del bitrate e l’audio.",
    "Jeder Dienst dekodiert; angezeigte Bitrate entspricht dem Label.": "Ogni servizio si decodifica; il bitrate indicato corrisponde all’etichetta.",
    "Schutz-Matrix (64 kbit/s)": "Matrice di protezione (64 kbit/s)",
    "Alle Schutzprofile anwählen; optional mit Pegelrampe die Empfangsschwelle je Profil bestimmen.": "Selezionare tutti i profili di protezione; facoltativamente determinare la soglia di ricezione per profilo con una rampa di livello.",
    "Alle Dienste dekodieren; stärkerer Schutz (1-A) hält bei geringerem Pegel länger durch.": "Tutti i servizi si decodificano; una protezione più forte (1-A) resiste più a lungo a livello basso.",
    "MP2-Dienste (DAB)": "Servizi MP2 (DAB)",
    "Klassisches DAB mit MPEG Layer II: Stereo, Joint, Dual, Mono, 24 kHz, UEP und EEP.": "DAB classico con MPEG Layer II: stereo, joint, dual, mono, 24 kHz, UEP ed EEP.",
    "MP2-Mischung": "Mix MP2",
    "Alle MP2-Dienste anwählen; Dual-Channel-Dienst auf Kanalwahl prüfen.": "Selezionare tutti i servizi MP2; verificare la selezione del canale del servizio dual-channel.",
    "Alle Dienste hörbar, Modus-Anzeige korrekt, 24-kHz-Dienst (LSF) wird unterstützt.": "Tutti i servizi udibili, indicazione modalità corretta, servizio a 24 kHz (LSF) supportato.",
    "Maximale Dienstanzahl": "Numero massimo di servizi",
    "Volle Ensembles mit vielen kleinen Diensten – Senderliste, Speicher und FIC-Last des Prüflings.": "Ensemble completi con molti piccoli servizi – elenco stazioni, memoria e carico FIC del dispositivo in prova.",
    "24 Dienste à 32 kbit/s (EEP 3-A)": "24 servizi a 32 kbit/s (EEP 3-A)",
    "Sendersuchlauf am Prüfling, Anzahl der gefundenen Dienste notieren. Hinweis: Viele Encoder belasten den Erzeuger stark – Testton statt Datei.": "Scansione delle stazioni sul dispositivo in prova, annotare il numero di servizi trovati. Nota: molti encoder caricano molto il generatore – tono di prova invece di file.",
    "24 Dienste gefunden, Labels vollständig, alphabetische Sortierung korrekt.": "24 servizi trovati, etichette complete, ordinamento alfabetico corretto.",
    "48 Dienste à 16 kbit/s (EEP 4-A)": "48 servizi a 16 kbit/s (EEP 4-A)",
    "Sendersuchlauf wiederholen. Grenzfall für die Senderliste und Labelanzeige.": "Ripetere la scansione delle stazioni. Caso limite per l’elenco stazioni e la visualizzazione delle etichette.",
    "Alle 48 Dienste werden gefunden oder der Prüfling meldet die Grenze sauber.": "Tutti i 48 servizi vengono trovati oppure il dispositivo in prova segnala correttamente il limite.",
    "Zeichensatz & Labels": "Set di caratteri ed etichette",
    "Grenzfälle für Labels und DLS: Umlaute, volle 16/8 Zeichen, UTF-8 mit Kyrillisch/Griechisch, lange DLS.": "Casi limite per etichette e DLS: dieresi, 16/8 caratteri pieni, UTF-8 con cirillico/greco, DLS lungo.",
