    "Label, Kurzlabel und DLS am Display prüfen (Umlaute, ß, Euro, Sonderzeichen).": "Verificare etichetta, etichetta breve e DLS sul display (dieresi, ß, euro, caratteri speciali).",
    "Alle Zeichen korrekt, kein Ersatzzeichen, Kurzlabel entspricht der Auswahl.": "Tutti i caratteri corretti, nessun carattere sostitutivo, etichetta breve conforme alla selezione.",
