    "Darstellung nicht-lateinischer Labels prüfen. UTF-8-Labels haben 16 Byte (nicht Zeichen).": "Verificare la visualizzazione di etichette non latine. Le etichette UTF-8 hanno 16 byte (non caratteri).",
