    "Prüfling auf „Musik“ stellen. Im Bereich Durchsagen zuerst Cluster 1 (Verkehr), dann den Alarm-Cluster aktivieren und wieder abschalten.": "Impostare il dispositivo in prova su «Musik». Nella sezione Annunci attivare prima il cluster 1 (traffico), poi il cluster allarme, e disattivarli di nuovo.",
    "Umschalten auf „Verkehr“-Dienst bei TA ein; Alarm unterbricht immer (auch bei TA aus); Rückkehr nach Ende.": "Commutazione sul servizio «Verkehr» con TA on; l’allarme interrompe sempre (anche con TA off); ritorno alla fine.",
    "Linking": "Linking",
    "Dienstverknüpfung zu UKW (FIG 0/21, PI) und anderen Ensembles (FIG 0/24).": "Collegamento dei servizi con FM (FIG 0/21, PI) e altri ensemble (FIG 0/24).",
    "UKW-Linking und Ensemble-Verweis": "Linking FM e rimando a ensemble",
    "Pegel absenken (Rampe), bis der DAB-Empfang abbricht. Verhalten des Prüflings beobachten (Wechsel auf UKW-PI D3C1 bzw. anderes Ensemble).": "Abbassare il livello (rampa) finché la ricezione DAB si interrompe. Osservare il comportamento del dispositivo in prova (passaggio a PI FM D3C1 o altro ensemble).",
    "Prüfling wechselt auf UKW mit passender PI oder meldet die Alternativen korrekt.": "Il dispositivo in prova passa in FM con PI corrispondente o segnala correttamente le alternative.",
