    "Ein Referenzdienst, Dämpfungsrampe 40 → 89 dB in 1-dB-Schritten zur Bestimmung der Empfangsschwelle.": "Un servizio di riferimento, rampa di attenuazione 40 → 89 dB a passi di 1 dB per determinare la soglia di ricezione.",
    "Referenzdienst + Rampe": "Servizio di riferimento + rampa",
