    "DVB-T K36 594 MHz · 8k 16-QAM 2/3 GI 1/4 · HD": "DVB-T K36 594 MHz · 8k 16-QAM 2/3 GI 1/4 · HD",
    "TV: Antenne → DVB-T → Suchlauf (oder manuell K36, 8 MHz). Dienst „DABLAB Test“ in HD (H.264 1080p25 + AAC), EIT prüfen. Modulator auf dem Pluto (8 MHz).": "TV: Antenna → DVB-T → scansione (o manuale K36, 8 MHz). Verificare il servizio «DABLAB Test» in HD (H.264 1080p25 + AAC) e l’EIT. Modulatore sul Pluto (8 MHz).",
    "Dienst „DABLAB Test“ in HD gefunden, Bild und Ton, EIT sichtbar.": "Servizio «DABLAB Test» trovato in HD, immagine e audio, EIT visibile.",
    "DVB-C 546 MHz · 64-QAM 6900 kBd · SD": "DVB-C 546 MHz · 64-QAM 6900 kBd · SD",
    "TV: Kabel → Suchlauf (vollständig oder manuell 546 MHz, 6900 kS/s, 64-QAM). Dienst „DABLAB Kabel“ prüfen.": "TV: Cavo → scansione (completa o manuale 546 MHz, 6900 kS/s, 64-QAM). Verificare il servizio «DABLAB Kabel».",
