    "Farbbalken mit Text „Feldtest TV“, Ton 1 kHz.": "Barre colore con testo «Feldtest TV», tono 1 kHz.",
    "DVB-S 11 038 MHz V · 22 000 kS/s · QPSK 7/8 · 3 Dienste (HD/UHD/HDR10)": "DVB-S 11 038 MHz V · 22 000 kS/s · QPSK 7/8 · 3 servizi (HD/UHD/HDR10)",
    "⚠️ DC-Block zwischen Pluto und Sat-Eingang! LNB-Speisung am Receiver aus. TV: Satellit → manueller Transponder 11 038 MHz V, 22 000 kS/s, LOF 9750 (Low-Band, 22 kHz aus) → Sat-ZF 1288 MHz. Modulator auf dem Pluto.": "⚠️ DC block tra Pluto e ingresso satellite! Alimentazione LNB del ricevitore disattivata. TV: Satellite → transponder manuale 11 038 MHz V, 22 000 kS/s, LOF 9750 (banda bassa, 22 kHz off) → IF sat 1288 MHz. Modulatore sul Pluto.",
    "Drei Dienste: HD (H.264), UHD (HEVC), HDR10 (HEVC Main10) – HDR-Kennung am TV.": "Tre servizi: HD (H.264), UHD (HEVC), HDR10 (HEVC Main10) – indicazione HDR sul TV.",
