    "Sat-Eingang führt 13/18 V – DC-Block bzw. LNB-Speisung am Receiver aus!": "Satellietingang voert 13/18 V – DC-blok of LNB-voeding op de ontvanger uit!",
    "Der Receiver speist über den Sat-Eingang das LNB (13 V = V, 18 V = H, 22 kHz = High-Band). Ohne DC-Block (Gleichspannungstrenner) zwischen Pluto-TX und Receiver wird der Pluto beschädigt. Zusätzlich LNB-Speisung im Receiver-Menü abschalten, wenn möglich.": "De ontvanger voedt de LNB via de satellietingang (13 V = V, 18 V = H, 22 kHz = hoge band). Zonder DC-blok tussen Pluto-TX en ontvanger raakt de Pluto beschadigd. Schakel indien mogelijk ook de LNB-voeding in het ontvangermenu uit.",
