    "Alle Codec-Kombinationen": "Alle codeccombinaties",
    "Jeden Dienst am Prüfling anwählen. Ton (unterschiedliche Frequenz je Dienst), Codec-Anzeige und Kanalzahl kontrollieren.": "Elke dienst op het testobject kiezen. Geluid (andere frequentie per dienst), codecweergave en aantal kanalen controleren.",
