    "MP2-Mischung": "MP2-mix",
    "Alle MP2-Dienste anwählen; Dual-Channel-Dienst auf Kanalwahl prüfen.": "Alle MP2-diensten kiezen; dual-channel-dienst op kanaalkeuze controleren.",
    "Alle Dienste hörbar, Modus-Anzeige korrekt, 24-kHz-Dienst (LSF) wird unterstützt.": "Alle diensten hoorbaar, modusweergave correct, 24-kHz-dienst (LSF) wordt ondersteund.",
