    "Volle Ensembles mit vielen kleinen Diensten – Senderliste, Speicher und FIC-Last des Prüflings.": "Volle ensembles met veel kleine diensten – zenderlijst, geheugen en FIC-belasting van het testobject.",
    "24 Dienste à 32 kbit/s (EEP 3-A)": "24 diensten à 32 kbit/s (EEP 3-A)",
    "Sendersuchlauf am Prüfling, Anzahl der gefundenen Dienste notieren. Hinweis: Viele Encoder belasten den Erzeuger stark – Testton statt Datei.": "Zenders zoeken op het testobject, aantal gevonden diensten noteren. Let op: veel encoders belasten de generator zwaar – testtoon in plaats van bestand.",
