    "Prüfling auf „Musik“ stellen. Im Bereich Durchsagen zuerst Cluster 1 (Verkehr), dann den Alarm-Cluster aktivieren und wieder abschalten.": "Testobject op ‘Musik’ zetten. In het onderdeel Omroepberichten eerst cluster 1 (verkeer), dan het alarmcluster activeren en weer uitschakelen.",
    "Umschalten auf „Verkehr“-Dienst bei TA ein; Alarm unterbricht immer (auch bei TA aus); Rückkehr nach Ende.": "Schakelt bij TA aan naar de dienst ‘Verkehr’; alarm onderbreekt altijd (ook bij TA uit); keert na afloop terug.",
