    "Alle Modulationsparameter brauchen „Übernehmen (Neustart)“. Die Nutzbitrate bestimmt das TS-Budget im Bereich „Programme“.": "Wszystkie parametry modulacji wymagają „Zastosuj (restart)”. Przepływność użyteczna wyznacza budżet TS w sekcji „Programy”.",
    "Symbolrate (kBd)": "Szybkość symbolowa (kBd)",
    "6,900 MBd = deutsches Kabel (Auto-Suchlauf), 6,875 Pflicht in Suchlauflisten, 3,450 MBd läuft per USB (manuelle Eingabe am Receiver)": "6,900 MBd = niemiecka kablówka (autowyszukiwanie), 6,875 obowiązkowe na listach wyszukiwania, 3,450 MBd działa przez USB (ręczne wprowadzenie w odbiorniku)",
    "Deutschland: 256-QAM; RRC α = 0,15": "Niemcy: 256-QAM; RRC α = 0,15",
    "Nutzbitrate = SR · log2(M) · 188/204. Für 6,9 MBd sind 13,8 MS/s nötig – nur zyklischer Puffer/Modulator auf dem Pluto.": "Przepływność użyteczna = SR · log2(M) · 188/204. Dla 6,9 MBd potrzeba 13,8 MS/s – tylko bufor cykliczny/modulator w Pluto.",
    "Sat-Eingang führt 13/18 V – DC-Block bzw. LNB-Speisung am Receiver aus!": "Wejście SAT podaje 13/18 V – blokada DC lub zasilanie LNB w odbiorniku wyłączone!",
    "Der Receiver speist über den Sat-Eingang das LNB (13 V = V, 18 V = H, 22 kHz = High-Band). Ohne DC-Block (Gleichspannungstrenner) zwischen Pluto-TX und Receiver wird der Pluto beschädigt. Zusätzlich LNB-Speisung im Receiver-Menü abschalten, wenn möglich.": "Odbiornik zasila LNB przez wejście SAT (13 V = V, 18 V = H, 22 kHz = pasmo górne). Bez blokady DC między Pluto TX a odbiornikiem Pluto zostanie uszkodzony. W miarę możliwości wyłącz też zasilanie LNB w menu odbiornika.",
    "Anwendung": "Zastosowanie",
    "Satellit (LNB, Sat-ZF)": "Satelita (LNB, p.cz. SAT)",
    "Amateurfunk (DATV)": "Krótkofalarstwo (DATV)",
    "DATV sendet direkt auf der Amateurfunkfrequenz, IQ per USB – nur mit Amateurfunkzulassung": "DATV nadaje bezpośrednio na częstotliwości amatorskiej, IQ przez USB – tylko z licencją krótkofalowca",
    "Amateurfunk: Senden nur mit gültiger Zulassung und eigenem Rufzeichen.": "Krótkofalarstwo: nadawanie tylko z ważną licencją i własnym znakiem wywoławczym.",
    "Der Pluto liefert höchstens +7 dBm; für QO-100 folgen Filter, Endstufe und Spiegel. Bandplan, Leistungsgrenzen und die Regeln des Transponders (BATC/AMSAT-DL) beachten. Stationskennung: das Rufzeichen steht im Programm-/Anbieternamen.": "Pluto daje najwyżej +7 dBm; dla QO-100 potrzebne są filtr, wzmacniacz i czasza. Przestrzegaj planu pasma, limitów mocy i zasad transpondera (BATC/AMSAT-DL). Identyfikacja stacji: znak wywoławczy jest w nazwie programu/dostawcy.",
