    "Alle Codec-Kombinationen": "Wszystkie kombinacje kodeków",
    "Jeden Dienst am Prüfling anwählen. Ton (unterschiedliche Frequenz je Dienst), Codec-Anzeige und Kanalzahl kontrollieren.": "Wybierz każdą usługę na urządzeniu badanym. Sprawdź dźwięk (inna częstotliwość dla każdej usługi), wskazanie kodeka i liczbę kanałów.",
