    "Alle Schutzprofile anwählen; optional mit Pegelrampe die Empfangsschwelle je Profil bestimmen.": "Wybierz wszystkie profile ochrony; opcjonalnie wyznacz próg odbioru dla każdego profilu rampą poziomu.",
    "Alle Dienste dekodieren; stärkerer Schutz (1-A) hält bei geringerem Pegel länger durch.": "Wszystkie usługi się dekodują; silniejsza ochrona (1-A) wytrzymuje dłużej przy niższym poziomie.",
    "MP2-Dienste (DAB)": "Usługi MP2 (DAB)",
    "Klassisches DAB mit MPEG Layer II: Stereo, Joint, Dual, Mono, 24 kHz, UEP und EEP.": "Klasyczny DAB z MPEG Layer II: stereo, joint, dual, mono, 24 kHz, UEP i EEP.",
    "MP2-Mischung": "Mieszanka MP2",
    "Alle MP2-Dienste anwählen; Dual-Channel-Dienst auf Kanalwahl prüfen.": "Wybierz wszystkie usługi MP2; sprawdź wybór kanału w usłudze dual-channel.",
    "Alle Dienste hörbar, Modus-Anzeige korrekt, 24-kHz-Dienst (LSF) wird unterstützt.": "Wszystkie usługi słyszalne, wskazanie trybu poprawne, usługa 24 kHz (LSF) obsługiwana.",
    "Maximale Dienstanzahl": "Maksymalna liczba usług",
    "Volle Ensembles mit vielen kleinen Diensten – Senderliste, Speicher und FIC-Last des Prüflings.": "Pełne multipleksy z wieloma małymi usługami – lista stacji, pamięć i obciążenie FIC urządzenia badanego.",
    "24 Dienste à 32 kbit/s (EEP 3-A)": "24 usługi po 32 kbit/s (EEP 3-A)",
    "Sendersuchlauf am Prüfling, Anzahl der gefundenen Dienste notieren. Hinweis: Viele Encoder belasten den Erzeuger stark – Testton statt Datei.": "Wyszukaj stacje na urządzeniu badanym, zanotuj liczbę znalezionych usług. Uwaga: wiele koderów mocno obciąża generator – ton testowy zamiast pliku.",
    "24 Dienste gefunden, Labels vollständig, alphabetische Sortierung korrekt.": "Znaleziono 24 usługi, etykiety kompletne, sortowanie alfabetyczne poprawne.",
    "48 Dienste à 16 kbit/s (EEP 4-A)": "48 usług po 16 kbit/s (EEP 4-A)",
    "Sendersuchlauf wiederholen. Grenzfall für die Senderliste und Labelanzeige.": "Powtórz wyszukiwanie stacji. Przypadek graniczny dla listy stacji i wyświetlania etykiet.",
